window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-adc74ef305df64d7"]={"versions": [{"id": "FIG-adc74ef305df64d7", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Methodikdiagramm (AUTOSAR Methodology Work Product / Activity View) im SPEM- bzw. UML-Aktivitätskontext. Das Diagramm modelliert die methodische Teilaktivität „Define BSW Module Timing“ innerhalb des Entwicklungsprozesses der AUTOSAR-Basissoffware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rolle</strong>: <code>Basic Software Module Developer</code> (ausführender Entwickler/Akteur).</li>\n<li><strong>Aktivität / Task</strong>: <code>Define BSW Module Timing</code> (Prozessschritt).</li>\n<li><strong>Eingangsartefakt</strong>: <code>Basic Software Module Internal</code> (abgeschnitten am Bildrand; AUTOSAR BSW Module Internal Behavior Description / XML-Artefakt) mit Multiplizität <code>1</code> und Stereotyp <code>«input»</code>.</li>\n<li><strong>Ausgangsartefakt</strong>: <code>Basic Software</code> (abgeschnitten am Bildrand; AUTOSAR BSW Module Timing / Timing Description Artefakt) mit Multiplizität <code>1</code> und Stereotyp <code>«output»</code>.</li>\n<li><strong>Beziehung</strong>: Assoziation von <code>Basic Software Module Developer</code> zu <code>Define BSW Module Timing</code> mit Stereotyp <code>«performs»</code> und Multiplizität <code>1</code> an der Aktivität.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>Basic Software Module Developer</code> initiiert und vollzieht die Aktivität <code>Define BSW Module Timing</code> (<code>«performs»</code>).</li>\n<li>Die Aktivität konsumiert genau ein Artefakt <code>Basic Software Module Internal</code> (<code>«input»</code>, Kardinalität 1).</li>\n<li>Die Aktivität erzeugt als Ergebnis genau ein Artefakt <code>Basic Software [...]</code> (<code>«output»</code>, Kardinalität 1), welches die Timing-Spezifikation für das betreffende BSW-Modul beinhaltet.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Vorgabe für die Modellierung von Timing-Eigenschaften auf BSW-Ebene. Entwickler müssen sicherstellen, dass vor der Durchführung der Aktivität das interne Modulverhalten (<code>Basic Software Module Internal Behavior</code>) formal vorliegt, um darauf aufbauend konsistente Timing-Beschreibungen (Events, Ausführungszeiten, Latenzen) zu spezifizieren. Multiplizitäten und Rollenzuordnungen sind für standardkonforme Toolchain-Integrationen verbindlich.</p>"}, {"id": "FIG-48f8099ee0958673", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Methodikdiagramm (AUTOSAR Methodology Work Product / Activity View) im SPEM- bzw. UML-Aktivitätskontext. Das Diagramm modelliert die methodische Teilaktivität „Define BSW Module Timing“ innerhalb des Entwicklungsprozesses der AUTOSAR-Basissoffware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rolle</strong>: <code>Basic Software Module Developer</code> (ausführender Entwickler/Akteur).</li>\n<li><strong>Aktivität / Task</strong>: <code>Define BSW Module Timing</code> (Prozessschritt).</li>\n<li><strong>Eingangsartefakt</strong>: <code>Basic Software Module Internal</code> (abgeschnitten am Bildrand; AUTOSAR BSW Module Internal Behavior Description / XML-Artefakt) mit Multiplizität <code>1</code> und Stereotyp <code>«input»</code>.</li>\n<li><strong>Ausgangsartefakt</strong>: <code>Basic Software</code> (abgeschnitten am Bildrand; AUTOSAR BSW Module Timing / Timing Description Artefakt) mit Multiplizität <code>1</code> und Stereotyp <code>«output»</code>.</li>\n<li><strong>Beziehung</strong>: Assoziation von <code>Basic Software Module Developer</code> zu <code>Define BSW Module Timing</code> mit Stereotyp <code>«performs»</code> und Multiplizität <code>1</code> an der Aktivität.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>Basic Software Module Developer</code> initiiert und vollzieht die Aktivität <code>Define BSW Module Timing</code> (<code>«performs»</code>).</li>\n<li>Die Aktivität konsumiert genau ein Artefakt <code>Basic Software Module Internal</code> (<code>«input»</code>, Kardinalität 1).</li>\n<li>Die Aktivität erzeugt als Ergebnis genau ein Artefakt <code>Basic Software [...]</code> (<code>«output»</code>, Kardinalität 1), welches die Timing-Spezifikation für das betreffende BSW-Modul beinhaltet.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Vorgabe für die Modellierung von Timing-Eigenschaften auf BSW-Ebene. Entwickler müssen sicherstellen, dass vor der Durchführung der Aktivität das interne Modulverhalten (<code>Basic Software Module Internal Behavior</code>) formal vorliegt, um darauf aufbauend konsistente Timing-Beschreibungen (Events, Ausführungszeiten, Latenzen) zu spezifizieren. Multiplizitäten und Rollenzuordnungen sind für standardkonforme Toolchain-Integrationen verbindlich.</p>"}], "trans": [{"from": "FIG-adc74ef305df64d7", "to": "FIG-48f8099ee0958673", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
